targets.query:
from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "weight_g")
  // quality is a soft-delete marker set by Node-RED (ok|empty) and by
  // mark-weight.sh after the fact. Nothing is dropped from the database; the
  // charts simply show the readings currently believed good.
  |> filter(fn: (r) => r.quality == "ok" and r.plant_id != "unknown")
  |> group(columns: ["plant_id"])
  |> sort(columns: ["_time"])
  |> keep(columns: ["_time", "_value", "plant_id"])

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "weight_g")
  // quality is a soft-delete marker set by Node-RED (ok|empty) and by
  // mark-weight.sh after the fact. Nothing is dropped from the database; the
  // charts simply show the readings currently believed good.
  |> filter(fn: (r) => r.quality == "ok" and r.plant_id != "unknown")
  |> group(columns: ["plant_id"])
  |> sort(columns: ["_time"])
  // Carry the weight and the timestamp as plain numbers, then take ONE difference
  // over both: the weight change and the time gap come out on the same row by
  // construction. Using elapsed() + difference() instead drops two rows rather than
  // one, so the first interval of every series vanished silently.
  |> map(fn: (r) => ({ r with w: r._value, t: float(v: int(v: r._time)) }))
  |> difference(columns: ["w", "t"], nonNegative: false)
  |> map(fn: (r) => ({ r with hours: r.t / 3600000000000.0 }))
  // A rate only means something across a GAP. Two readings from the same session —
  // a repeat, or the pre/post pair around watering — are minutes apart, and
  // dividing by that produces nonsense (one such pair works out at -10512 g/day).
  // This also guarantees the divisor is never zero.
  |> filter(fn: (r) => r.hours >= 1.0)
  // Sign flipped so positive = the plant drank it.
  |> map(fn: (r) => ({ r with _value: -r.w / r.hours * 24.0 }))
  |> keep(columns: ["_time", "_value", "plant_id"])

import "timezone"
option location = timezone.location(name: "Asia/Taipei")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "weight_g")
  |> filter(fn: (r) => r.quality == "ok" and r.plant_id != "unknown")
  |> group(columns: ["plant_id"])
  |> sort(columns: ["_time"])
  |> map(fn: (r) => ({ r with w: r._value, t: float(v: int(v: r._time)) }))
  |> difference(columns: ["w", "t"], nonNegative: false)
  |> map(fn: (r) => ({ r with hours: r.t / 3600000000000.0, _value: r.w }))
  // ESTIMATED: no pre-water weighing that session, so the pair spans a gap and the
  // figure is water added MINUS whatever the plant used in between. Worse, across a
  // gap the two populations overlap — the largest drift seen is +13.0 g and the
  // smallest real watering caught this way is +20.2 g, barely 7 g apart. 15 g is
  // therefore a judgement call, not a clean separation; treat these bars as a hint
  // and fix the protocol instead (always weigh before watering).
  |> filter(fn: (r) => r.hours >= 1.0 and r._value > 15.0)
  |> keep(columns: ["_time", "_value", "plant_id"])
  |> yield(name: "estimated")

import "date"
import "timezone"
option location = timezone.location(name: "Asia/Taipei")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "light" and r._field == "on" and r._value == 0.0)
  |> map(fn: (r) => ({ r with _value: float(v: date.hour(t: r._time)) + float(v: date.minute(t: r._time)) / 60.0 }))
  // Keep only plausible lamp-off times. `light/state` is RETAINED, so every
  // Telegraf reconnect replays it and lands a phantom OFF at the restart time —
  // one such artifact sits at 22:44 on 2026-07-30. The real switch-off is always
  // in the evening window, so anything outside it is not a lamp event.
  |> filter(fn: (r) => r._value >= 17.0 and r._value <= 21.5)
  |> aggregateWindow(every: 1d, fn: last, createEmpty: false)
  |> keep(columns: ["_time", "_value"])
  |> yield(name: "lamp off (hour of day)")

import "timezone"
option location = timezone.location(name: "Asia/Taipei")

base = from(bucket: "sensors") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)

// One representative field per measurement — counting every field would mix
// value types in one group, which aggregateWindow rejects.
union(tables: [
  base |> filter(fn: (r) => r._measurement == "air" and r._field == "lux"),
  base |> filter(fn: (r) => r._measurement == "spectrum" and r._field == "f555"),
  base |> filter(fn: (r) => r._measurement == "weather" and r._field == "temperature_2m"),
  base |> filter(fn: (r) => r._measurement == "plant_weight" and r._field == "weight_g"),
  // The alert-delivery scrape. If this row goes flat, we have stopped being able to
  // tell whether warnings reach anyone — the same blindness as 2026-08-08, one
  // level up. It is absent until Grafana's first notification attempt after a
  // restart, so a gap right after a restart is expected, not a fault.
  base |> filter(fn: (r) => r._measurement == "grafana_alerting_notifications_total" and r._field == "counter"),
])
  |> group(columns: ["_measurement"])
  |> aggregateWindow(every: 1d, fn: count, createEmpty: true)
  |> keep(columns: ["_time", "_value", "_measurement"])
